const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const lakeElton = ee.Geometry.Point(46.66, 49.33).buffer(5000); // Approximate center of Lake Elton, buffered by 5km
  const year2004 = '2004-01-01';
  const end2004 = '2004-12-31';
  const year2009 = '2009-01-01';
  const end2009 = '2009-12-31';
  const band = 'B3'; // Red band for surface reflectance

  // Cloud masking function for Landsat 5 SR data
  function maskL5SrClouds(image) {
    const qa = image.select('pixel_qa');
    // Bits 3 and 5 are cloud shadow and cloud, respectively.
    // Bit 9 is high confidence cloud.
    const cloudShadowBitMask = (1 << 3);
    const cloudsBitMask = (1 << 5);
    const highCloudConfBitMask = (1 << 9);

    // Both flags should be set to 0 for clear conditions.
    const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                 .and(qa.bitwiseAnd(cloudsBitMask).eq(0))
                 .and(qa.bitwiseAnd(highCloudConfBitMask).eq(0));

    // Apply the scaling factors for SR bands and mask clouds.
    return image.updateMask(mask).multiply(0.0001).select(['B1', 'B2', 'B3', 'B4', 'B5', 'B7']);
  }

  // Function to process data for a given year
  async function processYear(start, end, geometry, year_str) {
    let collection = ee.ImageCollection('LANDSAT/LT05/C01/T1_SR')
                       .filterBounds(geometry)
                       .filterDate(start, end);

    const initialSize = await collection.size().getInfo();
    if (initialSize === 0) {
      console.log(`${year_str} Images: 0`);
      return { meanReflectance: null, validPixels: 0 };
    }

    collection = collection.map(maskL5SrClouds);

    // Take the median composite to represent the year
    const composite = collection.median();

    if (composite === null) {
      console.log(`${year_str} Images: ${initialSize} (Val: No composite)`);
      return { meanReflectance: null, validPixels: 0 };
    }

    // Calculate mean reflectance and valid pixels for the band
    const stats = await composite.select(band).reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: geometry,
      scale: 30, // Landsat resolution
      maxPixels: 1e9
    }).getInfo();

    const meanReflectance = stats ? stats[band] : null;
    const validPixels = stats ? stats[`${band}_count`] : 0;

    console.log(`${year_str} Images: ${initialSize} (Val: ${validPixels})`);

    return { meanReflectance, validPixels };
  }

  // 2. Data Acquisition & Check for 2004
  const result2004 = await processYear(year2004, end2004, lakeElton, "2004");
  const meanReflectance2004 = result2004.meanReflectance;
  const validPixels2004 = result2004.validPixels;

  if (meanReflectance2004 === null && validPixels2004 === 0) {
    if ((await ee.ImageCollection('LANDSAT/LT05/C01/T1_SR').filterBounds(lakeElton).filterDate(year2004, end2004).size().getInfo()) === 0) {
      console.log("No data for 2004.");
      console.log("C1");
      return;
    } else {
      console.log("No valid pixels for 2004 after masking.");
      console.log("C2");
      return;
    }
  }

  // 2. Data Acquisition & Check for 2009
  const result2009 = await processYear(year2009, end2009, lakeElton, "2009");
  const meanReflectance2009 = result2009.meanReflectance;
  const validPixels2009 = result2009.validPixels;

  if (meanReflectance2009 === null && validPixels2009 === 0) {
    if ((await ee.ImageCollection('LANDSAT/LT05/C01/T1_SR').filterBounds(lakeElton).filterDate(year2009, end2009).size().getInfo()) === 0) {
      console.log("No data for 2009.");
      console.log("C1");
      return;
    } else {
      console.log("No valid pixels for 2009 after masking.");
      console.log("C2");
      return;
    }
  }

  // 4. Calculation & Validation
  if (meanReflectance2004 === null || isNaN(meanReflectance2004) ||
      meanReflectance2009 === null || isNaN(meanReflectance2009)) {
    console.log("Calculation failure: one or both reflectance values are invalid.");
    console.log("C3");
    return;
  }

  console.log(`2004 Mean Reflectance (${band}): ${meanReflectance2004.toFixed(4)}`);
  console.log(`2009 Mean Reflectance (${band}): ${meanReflectance2009.toFixed(4)}`);

  // 5. Final Answer
  if (meanReflectance2009 > meanReflectance2004) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
